CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT, role TEXT NOT NULL DEFAULT 'pharmacist' CHECK (role IN ('admin','pharmacist','coordinator')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS medicines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trade_name TEXT NOT NULL, scientific_name TEXT, active_ingredient TEXT, barcode TEXT UNIQUE, cost_price NUMERIC(12,2) DEFAULT 0, selling_price NUMERIC(12,2) DEFAULT 0, stock_quantity INTEGER NOT NULL DEFAULT 0, min_stock_alert INTEGER NOT NULL DEFAULT 5, expiry_date DATE, batch_number TEXT, manufacturer TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT, address TEXT, credit_balance NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT, company_name TEXT, balance_due NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sales (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number TEXT UNIQUE NOT NULL, customer_id UUID REFERENCES customers(id), total_amount NUMERIC(12,2) NOT NULL DEFAULT 0, discount NUMERIC(12,2) NOT NULL DEFAULT 0, payment_type TEXT NOT NULL DEFAULT 'cash' CHECK (payment_type IN ('cash','card','credit')), whatsapp_sent BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sale_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id) ON DELETE CASCADE, medicine_id UUID NOT NULL REFERENCES medicines(id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price NUMERIC(12,2) NOT NULL, total_price NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID REFERENCES suppliers(id), total_cost NUMERIC(12,2) NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, medicine_id UUID NOT NULL REFERENCES medicines(id), quantity INTEGER NOT NULL, cost_price NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS debts_ledger (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES customers(id), sale_id UUID REFERENCES sales(id), amount NUMERIC(12,2) NOT NULL, transaction_type TEXT NOT NULL CHECK (transaction_type IN ('debit','payment')), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS medicines_search_idx ON medicines USING gin (to_tsvector('simple', coalesce(trade_name,'') || ' ' || coalesce(scientific_name,'') || ' ' || coalesce(active_ingredient,'')));
CREATE INDEX IF NOT EXISTS medicines_expiry_idx ON medicines(expiry_date);
CREATE INDEX IF NOT EXISTS debts_customer_idx ON debts_ledger(customer_id, created_at DESC);
